content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "FABS",
      "description": "Federal Assistance Broker System – manages financial assistance data submissions",
      "attributes": "Historical Data, System Rules"
    },
    {
      "name": "Historical Data",
      "description": "old records of data"
    },
    {
      "name": "System Rules",
      "description": "set of rules that determines the regulations for submission and data handling"
    },
    {
      "name": "DABS",
      "description": "Data Act Broker System – related system for managing different financial data sets",
      "attributes": "System Rules"
    },
    {
      "name": "FDPS",
      "description": "Federal Procurement Data System – database of government contract and procurement data",
      "attributes": "System Rules"
    },
    {
      "name": "Submission",
      "description": "a file or dataset uploaded to report financial data",
      "attributes": "Status, Deadline, Submission Data, Notification"
    },
    {
      "name": "Submission Data",
      "description": "Included in Submission by Agency"
    },
    {
      "name": "Status",
      "description": "the state of the submission"
    },
    {
      "name": "Deadline",
      "description": "time at which the submission is due"
    },
    {
      "name": "Notification",
      "description": "a reminder to a submitting party that certain data should be submitted in time"
    },
    {
      "name": "Agency User",
      "description": "a government employee submitting data for their agency"
    },
    {
      "name": "Published Data",
      "description": "data available to users of the broker system"
    },
    {
      "name": "Broker",
      "description": "Shared Frontend to FABS and DABS via which Users access the system",
      "attributes": "System Performance, Design"
    },
    {
      "name": "System Performance",
      "description": "Metrics that determine the performance and functionality of the system"
    },
    {
      "name": "Design",
      "description": "the design of the Broker"
    },
    {
      "name": "Broker User",
      "description": "someone accessing the services of the broker system"
    },
    {
      "name": "Developer",
      "description": "a technical member who implements and maintains functions of the broker system"
    },
    {
      "name": "Data User",
      "description": "Someone who accesses official financial data"
    },
    {
      "name": "Test",
      "description": "a unit that determines the functionality of the Design",
      "attributes": "Result"
    },
    {
      "name": "Owner",
      "description": "stakeholder in charge of product direction and improvement"
    },
    {
      "name": "UI Designer",
      "description": "shapes the design of the broker"
    },
    {
      "name": "Field Derivation",
      "description": "analytical data derived from the system"
    },
    {
      "name": "Tester",
      "description": "examines functionality of Field Derivation"
    }
  ]
}
```
